:root {
  --green: #00824A;
  --forest: #32462F;
  --cream: #F3CEA1;
  --coffee: #6A4B3A;
  --latte: #fffaf3;
  --text: #2f2b28;
  --muted: #6d655f;
  --card: #ffffff;
  --border: #e8dfd5;
  --shadow: 0 10px 30px rgba(50, 70, 47, 0.1);
  --radius: 16px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: "Inter", "DM Sans", system-ui, -apple-system, Segoe UI, sans-serif;
  color: var(--text);
  background: var(--latte);
  line-height: 1.55;
}
h1,h2,h3,h4 { font-family: "DM Sans", "Inter", sans-serif; color: var(--forest); margin: 0 0 .6rem; }
a { color: inherit; text-decoration: none; }
.container { width: min(1120px, 92vw); margin: 0 auto; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 44px; padding: .72rem 1.2rem; border-radius: 999px;
  border: 0; cursor: pointer; font-weight: 700;
}
.btn-primary { background: var(--green); color: #fff; }
.btn-secondary { background: #fff; border: 1px solid var(--border); color: var(--forest); }
.btn-primary:hover { filter: brightness(1.05); }
.topbar { background: #fff; border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 20; }
.nav { display: flex; align-items: center; justify-content: space-between; min-height: 72px; gap: 1rem; }
.brand { font-weight: 800; font-size: 1.2rem; color: var(--green); }
.brand span { color: var(--coffee); }
.nav-links { display: flex; gap: 1rem; flex-wrap: wrap; }
.nav-links a { padding: .55rem .8rem; border-radius: 999px; font-weight: 600; color: var(--forest); }
.nav-links a.active, .nav-links a:hover { background: #ecf7f1; }
.hero {
  background: linear-gradient(135deg, #ecf7f1 0%, #fff6ea 100%);
  padding: 4rem 0 3rem;
}
.hero-grid { display: grid; grid-template-columns: 1.15fr .85fr; gap: 1.5rem; align-items: center; }
.hero-card, .card { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); }
.hero-card { padding: 2rem; }
.kicker { color: var(--green); font-weight: 700; letter-spacing: .02em; }
.media {
  min-height: 250px; border-radius: var(--radius); overflow: hidden;
  background: linear-gradient(140deg, #9d6f52, #d7b08b 46%, #597152);
  display: grid; place-items: end start; padding: 1rem; color: #fff; font-weight: 700;
}
.section { padding: 3rem 0; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.padded { padding: 1.2rem; }
.muted { color: var(--muted); }
.cookie {
  position: fixed; left: 50%; bottom: 1rem; transform: translateX(-50%);
  background: #fff; border: 1px solid var(--border); border-radius: 12px;
  box-shadow: var(--shadow); width: min(840px, 94vw); padding: .9rem 1rem;
  display: flex; gap: 1rem; align-items: center; justify-content: space-between; z-index: 50;
}
.footer { background: #fff; border-top: 1px solid var(--border); padding: 2rem 0; }
.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.footer h4 { font-size: 1rem; }
.footer a { display: block; padding: .25rem 0; color: var(--muted); }
.footer-toggle { display:none; }
.page-title { padding: 2rem 0 1rem; }
.layout { display: grid; grid-template-columns: 250px 1fr; gap: 1rem; }
.sidebar { position: sticky; top: 84px; align-self: start; }
.sidebar a { display:block; padding:.6rem .8rem; border-radius:10px; color:var(--forest); }
.sidebar a:hover { background:#ecf7f1; }
.tabs { display:flex; flex-wrap:wrap; gap:.5rem; margin-bottom:1rem; }
.tab-btn { border:1px solid var(--border); background:#fff; color:var(--forest); border-radius:999px; padding:.5rem .9rem; min-height:44px; font-weight:700; cursor:pointer; }
.tab-btn.active { background: var(--green); color:#fff; border-color:var(--green); }
.tab-panel { display:none; }
.tab-panel.active { display:block; }
.carousel { position: relative; }
.carousel-track { display:grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.carousel-controls { display:flex; gap:.5rem; justify-content:flex-end; margin-bottom:.7rem; }
.icon-btn { width:44px; height:44px; border-radius:50%; border:1px solid var(--border); background:#fff; cursor:pointer; }
.store-top { display:grid; grid-template-columns: 1.2fr auto auto; gap:.7rem; align-items:center; }
input, select { min-height:44px; border-radius:10px; border:1px solid var(--border); padding:.6rem .75rem; font: inherit; }
.chip-toggle { display:inline-flex; border:1px solid var(--border); border-radius:999px; overflow:hidden; }
.chip-toggle button { min-height:44px; border:0; padding:0 1rem; background:#fff; cursor:pointer; font-weight:700; }
.chip-toggle button.active { background:var(--green); color:#fff; }
.suggestions { border:1px solid var(--border); border-radius:10px; margin-top:.3rem; background:#fff; display:none; }
.suggestions button { width:100%; text-align:left; border:0; background:#fff; padding:.55rem .7rem; cursor:pointer; }
.suggestions button:hover { background:#f6f5f3; }
.map { min-height:320px; border-radius: var(--radius); background: linear-gradient(160deg,#dce8d7,#efe4d6); border:1px solid var(--border); display:grid; place-items:center; color:var(--forest); font-weight:700; }
@media (max-width: 920px) {
  .hero-grid, .grid-3, .grid-2, .layout, .store-top { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .carousel-track { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 680px) {
  .nav { min-height: auto; padding: .7rem 0; align-items: flex-start; }
  .nav-links { width: 100%; }
  .cookie { flex-direction: column; align-items: flex-start; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-section { border-top:1px solid var(--border); padding:.5rem 0; }
  .footer-toggle { display:flex; width:100%; justify-content:space-between; align-items:center; border:0; background:none; padding:.6rem 0; font:inherit; font-weight:700; color:var(--forest); cursor:pointer; min-height:44px; }
  .footer-links { display:none; padding-bottom:.5rem; }
  .footer-section.open .footer-links { display:block; }
  .carousel-track { grid-template-columns: 1fr; }
}
